@page "/inventory"
@rendermode InteractiveServer
@using InventoryApp.Services
@inject EquipmentService EquipmentSvc
@inject PersistentComponentState ApplicationState
@implements IDisposable

<PageTitle>Inventory</PageTitle>

<h1>Equipment Inventory</h1>

@if (_items is null)
{
    <p><em>Loading inventory...</em></p>
}
else
{
    <table class="table">
        <thead>
            <tr>
                <th>Id</th>
                <th>Name</th>
                <th>Location</th>
                <th>Last Inspected</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var item in _items)
            {
                <tr>
                    <td>@item.Id</td>
                    <td>@item.Name</td>
                    <td>@item.Location</td>
                    <td>@item.LastInspected.ToShortDateString()</td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    private IReadOnlyList<EquipmentItem>? _items;
    private PersistingComponentStateSubscription _persistSub;

    protected override async Task OnInitializedAsync()
    {
        // During the interactive render, try to restore persisted state first.
        // If the data was already fetched during prerender it will be available
        // here, avoiding a second call to EquipmentService.
        if (ApplicationState.TryTakeFromJson<EquipmentItem[]>(
                "inventory", out var persisted))
        {
            _items = persisted;
        }
        else
        {
            _items = await EquipmentSvc.GetAllAsync();
        }

        // Register a callback that fires during prerender to persist the data
        // so the interactive render can pick it up without re-fetching.
        _persistSub = ApplicationState.RegisterOnPersisting(() =>
        {
            ApplicationState.PersistAsJson("inventory", _items);
            return Task.CompletedTask;
        });
    }

    public void Dispose() => _persistSub.Dispose();
}

